1	import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
2	import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
3	import { PaperclipApiClient } from "./client.js";
4	import { readConfigFromEnv, type PaperclipMcpConfig } from "./config.js";
5	import { createToolDefinitions } from "./tools.js";
6	
7	export function createPaperclipMcpServer(config: PaperclipMcpConfig = readConfigFromEnv()) {
8	  const server = new McpServer({
9	    name: "paperclip",
10	    version: "0.1.0",
11	  });
12	
13	  const client = new PaperclipApiClient(config);
14	  const tools = createToolDefinitions(client);
15	  for (const tool of tools) {
16	    server.tool(tool.name, tool.description, tool.schema.shape, tool.execute);
17	  }
18	
19	  return {
20	    server,
21	    tools,
22	    client,
23	  };
24	}
25	
26	export async function runServer(config: PaperclipMcpConfig = readConfigFromEnv()) {
27	  const { server } = createPaperclipMcpServer(config);
28	  const transport = new StdioServerTransport();
29	  await server.connect(transport);
30	}
